import glob
from PIL import Image

# Check what files exist in the train directory
train_dir = 'data_small/chest-xray-pneumonia/chest_xray/train'

if os.path.exists(train_dir):
    # Get all image files in subdirectories
    all_files = []
    for class_dir in os.listdir(train_dir):
        class_path = os.path.join(train_dir, class_dir)
        if os.path.isdir(class_path):
            files = glob.glob(os.path.join(class_path, '*'))
            print(f"{class_dir}: {len(files)} files")
