    print(f"\nTotal files in train directory: {len(all_files)}")

    # Try to open and identify images
    corrupted_files = []
    for img_path in all_files:
        try:
            with Image.open(img_path) as img:
                img.verify()
        except Exception as e:
            print(f"Corrupted file: {img_path} - Error: {e}")
            corrupted_files.append(img_path)

    if corrupted_files:
        print(f"\nFound {len(corrupted_files)} corrupted files")
    else:
        print("\nNo corrupted files found with PIL.fff")
else:
    print(f"Directory does not exist: {train_dir}")"}

